\title{The Chromatic Number of the Sudoku Constraint Graph, and the Phase
Transition of Random Sudoku}
\author{Aristotle}
\date{2026-07-10}

\begin{document}

\begin{abstract}
We study $n$-Sudoku --- the natural generalization of the familiar $9\times 9$
puzzle to an $n^2\times n^2$ grid with $n^2$ symbols --- as a constraint
satisfaction problem, and make precise its classical correspondence with graph
coloring. We introduce the \emph{Sudoku constraint graph} $G_n$, whose vertices
are the $n^4$ cells and whose edges join any two distinct cells sharing a row, a
column, or an $n\times n$ block. Our main structural results are: (i) a
\emph{bridge theorem} identifying valid Sudoku solutions with proper vertex
colorings of $G_n$; (ii) an explicit closed-form completion of the empty grid,
proving that every $n$-Sudoku is solvable; and (iii) the exact determination of
the \emph{chromatic number} $\chi(G_n) = n^2$. We then formulate the
\emph{phase-transition conjecture}: random $n$-Sudoku undergoes a sharp
solvability transition at clue density $d_c(n) = (n^2-1)/n^2$, with backtracking
hardness peaking at criticality and scaling as $\exp(\Theta(n^2))$. We explain
how the chromatic-number invariant is the deterministic backbone of a rigorous
threshold analysis.
\end{abstract}

\maketitle

\section{Introduction}
Sudoku is arguably the world's most popular constraint satisfaction problem
(CSP). Its rules are elementary, yet the difficulty of individual instances
varies enormously, and the decision problem for the generalized game is
NP-complete. This paper develops the structure explaining \emph{why}, by
exploiting a bridge between constraint satisfaction and graph coloring. The
central object is the Sudoku constraint graph $G_n$. We prove that valid
solutions are exactly the proper colorings of $G_n$, that $\chi(G_n)=n^2$, and
that the empty grid always admits a closed-form completion. We then use these
deterministic facts to frame the probabilistic phase-transition conjecture for
random Sudoku.

\section{Definitions}
Fix an integer $n\ge 1$, the \emph{order} of the puzzle; the classic game is
$n=3$.

\begin{definition}[Cells]
The set of \emph{cells} is $\Cell(n) = \{0,\dots,n^2-1\}\times\{0,\dots,n^2-1\}$,
with $|\Cell(n)| = n^4$.
\end{definition}

\begin{definition}[Constraint relations]
For $p=(r,c)$, $q=(r',c')$:
$\sameRow(p,q)\iff r=r'$; $\sameCol(p,q)\iff c=c'$;
$\sameBox(p,q)\iff \lfloor r/n\rfloor=\lfloor r'/n\rfloor \text{ and }
\lfloor c/n\rfloor=\lfloor c'/n\rfloor$.
Each relation is reflexive and symmetric.
\end{definition}

\begin{definition}[Filling and solution]
A \emph{filling} is $g:\Cell(n)\to\{0,\dots,n^2-1\}$. It is a \emph{valid Sudoku
solution} if for all distinct $p,q$ sharing a row, column, or block,
$g(p)\ne g(q)$.
\end{definition}

\begin{definition}[Sudoku constraint graph]
$G_n$ is the simple graph on $\Cell(n)$ with
$p\sim q \iff p\ne q \text{ and } (\sameRow(p,q)\lor\sameCol(p,q)\lor
\sameBox(p,q))$. Adjacency is symmetric and loopless.
\end{definition}

\begin{definition}[Proper coloring, chromatic number, clique]
A \emph{proper coloring} of $G$ with color set $S$ is $g:V(G)\to S$ with
$g(p)\ne g(q)$ whenever $p\sim q$; the \emph{chromatic number} $\chi(G)$ is the
least number of colors admitting a proper coloring. A \emph{clique} is a set of
pairwise adjacent vertices; a clique of size $k$ forces $\chi(G)\ge k$.
\end{definition}

\section{The Bridge Theorem}
\begin{theorem}[Bridge]\label{thm:bridge}
A filling $g$ is a valid Sudoku solution if and only if it is a proper coloring
of $G_n$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) If $g$ is a valid solution and $p\sim q$, then $p\ne q$ and they
share a row, column, or block; the corresponding solution clause gives
$g(p)\ne g(q)$. ($\Leftarrow$) If $g$ is a proper coloring, any two distinct cells
in a common row/column/block are adjacent, so $g(p)\ne g(q)$; all three solution
clauses hold.
\end{proof}

\begin{corollary}
The number of completed $n$-Sudoku grids equals $P(G_n, n^2)$, the chromatic
polynomial of $G_n$ evaluated at $n^2$. For $n=3$ this number is
$6{,}670{,}903{,}752{,}021{,}072{,}936{,}960$.
\end{corollary}

\section{An explicit solution of the empty grid}
\begin{definition}[Shift construction]
For integers $r,c$, set
$\sVal(n,r,c) = \bigl(n\,(r\bmod n) + \lfloor r/n\rfloor + c\bigr)\bmod n^2$.
For $n\ge 1$ this lies in $\{0,\dots,n^2-1\}$.
\end{definition}

\begin{lemma}[Base-$n$ digit uniqueness]\label{lem:digit}
If $b,b'<n$ and $na+b=na'+b'$, then $a=a'$ and $b=b'$.
\end{lemma}
\begin{proof}
Reducing mod $n$ gives $b=b'$; cancelling $n$ gives $a=a'$.
\end{proof}

\begin{lemma}[Modular cancellation]\label{lem:cancel}
If $x,y<N$ and $(k+x)\bmod N=(k+y)\bmod N$, then $x=y$; symmetrically for
$(x+k)$.
\end{lemma}

\begin{theorem}[Correctness]\label{thm:shift}
For $n\ge 1$, $g(r,c)=\sVal(n,r,c)$ is a valid Sudoku solution.
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Rows:} fixing $r$, $g(r,c)=(K+c)\bmod n^2$ with $K$ constant; Lemma
\ref{lem:cancel} gives $c=c'$. \emph{Columns:} $g(r,c)=(D_r+c)\bmod n^2$ with
$D_r=n(r\bmod n)+\lfloor r/n\rfloor<n^2$; cancelling $c$ gives $D_r=D_{r'}$, and
$D_r$ is $r$ in base $n$ with digits swapped, so Lemma \ref{lem:digit} gives
$r=r'$. \emph{Blocks:} using
$n(a\bmod n)+\lfloor a/n\rfloor+b=(n(a\bmod n)+(b\bmod n))+(\lfloor a/n\rfloor
+n\lfloor b/n\rfloor)$, equal block indices cancel the high terms; Lemma
\ref{lem:cancel} then reduces to $n(r\bmod n)+(c\bmod n)=n(r'\bmod n)+(c'\bmod
n)$, and Lemma \ref{lem:digit} yields $r=r'$, $c=c'$.
\end{proof}

\begin{corollary}
Every empty $n$-Sudoku ($n\ge 1$) is solvable; equivalently $G_n$ is
$n^2$-colorable.
\end{corollary}

\section{The chromatic number}
\begin{theorem}\label{thm:chi}
For $n\ge 1$, $\chi(G_n)=n^2$.
\end{theorem}
\begin{proof}
\emph{Lower bound.} The first row $\{(0,c):0\le c<n^2\}$ is a clique of size
$n^2$, so $\chi(G_n)\ge n^2$. \emph{Upper bound.} The shift construction
(Theorem \ref{thm:shift}) is, by Theorem \ref{thm:bridge}, a proper
$n^2$-coloring, so $\chi(G_n)\le n^2$. Hence $\chi(G_n)=n^2$.
\end{proof}

Since $\omega(G_n)\ge n^2$ (the row clique) and $\omega\le\chi=n^2$, we obtain
$\omega(G_n)=n^2$: the largest set of mutually constrained cells has size exactly
$n^2$.

\section{The phase-transition conjecture}
A \emph{Sudoku puzzle} is a partial filling on a clue set $C\subseteq\Cell(n)$; a
solution is a valid completion. In graph terms this is a \emph{precoloring
extension} problem for $G_n$, whose NP-completeness is exactly that of generalized
Sudoku. Let $p_{\mathrm{sol}}(n,d)$ be the probability a random puzzle of clue
density $d=|C|/n^4$ is solvable.

\begin{conjecture}[Solvability transition]
As $n\to\infty$, $p_{\mathrm{sol}}(n,d)$ has a sharp threshold at
$d_c(n)=\dfrac{n^2-1}{n^2}$: for fixed $\varepsilon>0$,
$p_{\mathrm{sol}}\to 1$ if $d\le d_c-\varepsilon$ and $p_{\mathrm{sol}}\to 0$ if
$d\ge d_c+\varepsilon$.
\end{conjecture}

Numerically $d_c(2)=0.75$, $d_c(3)\approx 0.889$, $d_c(4)\approx 0.9375$, with
$d_c(n)\to 1$. Heuristically each cell lies in cliques of size $n^2$; when about
$n^2-1$ of each $n^2$ cells are fixed the last degree of freedom vanishes, giving
critical free fraction $1/n^2$ and clue density $1-1/n^2$.

\begin{conjecture}[Hardness at criticality]
For backtracking search, expected solving time has an easy--hard--easy profile in
$d$, peaking at $d_c(n)$ where $T(n,d_c)=\exp(\Theta(n^2))$.
\end{conjecture}

Both are precise, empirically supported, and (to our knowledge) unproved --- the
Sudoku analogues of random $k$-SAT thresholds. Theorem \ref{thm:chi} is the
deterministic backbone: the critical clique of size $n^2$ and the value
$\chi=\omega=n^2$ are the inputs a second-moment or interpolation analysis would
require.

\section{Applications and future directions}
The bridge places Sudoku among mainstream coloring applications: exam/sports
scheduling, register allocation, and frequency assignment. Dropping block
constraints yields the rook's graph, whose $n^2$-colorings are the Latin squares
of order $n^2$; $G_n$ refines it by the block relation. Natural next steps:
compute further invariants of $G_n$; develop the chromatic-polynomial count of
grids; formalize the rook-graph $\to$ Sudoku-graph tower; study precoloring
extension as a complexity bridge; and pursue a rigorous proof of the
phase-transition conjectures via random-CSP methods.

\end{document}

