"""Demo: the shift construction solves every empty n-Sudoku."""
from __future__ import annotations
from typing import List


def sudoku_val(n: int, r: int, c: int) -> int:
    return (n * (r % n) + r // n + c) % (n * n)


def shift_grid(n: int) -> List[List[int]]:
    m = n * n
    return [[sudoku_val(n, r, c) for c in range(m)] for r in range(m)]


def is_valid(n: int, grid: List[List[int]]) -> bool:
    m = n * n
    def ok(vals: List[int]) -> bool:
        return sorted(vals) == list(range(m))
    if not all(ok(grid[r]) for r in range(m)):
        return False
    if not all(ok([grid[r][c] for r in range(m)]) for c in range(m)):
        return False
    for br in range(n):
        for bc in range(n):
            block = [grid[br * n + i][bc * n + j] for i in range(n) for j in range(n)]
            if not ok(block):
                return False
    return True


if __name__ == "__main__":
    for n in (2, 3, 4):
        g = shift_grid(n)
        print(f"n={n}: {n*n}x{n*n} grid valid = {is_valid(n, g)}")

"""Demo: valid solutions are exactly proper colorings (bridge theorem)."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Tuple

Cell = Tuple[int, int]


def adjacent(n: int, p: Cell, q: Cell) -> bool:
    if p == q:
        return False
    return (p[0] == q[0] or p[1] == q[1]
            or (p[0] // n == q[0] // n and p[1] // n == q[1] // n))


def cells(n: int) -> List[Cell]:
    m = n * n
    return [(r, c) for r in range(m) for c in range(m)]


def is_valid_solution(n: int, g: Dict[Cell, int]) -> bool:
    return all(not (adjacent(n, p, q) and g[p] == g[q])
               for p, q in combinations(cells(n), 2))


def is_proper_coloring(n: int, g: Dict[Cell, int]) -> bool:
    return all(g[p] != g[q]
               for p, q in combinations(cells(n), 2) if adjacent(n, p, q))


if __name__ == "__main__":
    n = 2
    m = n * n
    good = {(r, c): (n * (r % n) + r // n + c) % m for r in range(m) for c in range(m)}
    bad = dict(good)
    bad[(0, 0)] = bad[(0, 1)]  # break a row
    for name, g in [("valid grid", good), ("broken grid", bad)]:
        print(f"{name}: solution={is_valid_solution(n, g)}, "
              f"coloring={is_proper_coloring(n, g)}, "
              f"agree={is_valid_solution(n, g) == is_proper_coloring(n, g)}")

"""Demo: empirical solvability phase transition for random puzzles."""
from __future__ import annotations
import random
from itertools import combinations
from typing import Dict, List, Optional, Tuple

Cell = Tuple[int, int]


def adjacent(n: int, p: Cell, q: Cell) -> bool:
    if p == q:
        return False
    return (p[0] == q[0] or p[1] == q[1]
            or (p[0] // n == q[0] // n and p[1] // n == q[1] // n))


def cells(n: int) -> List[Cell]:
    m = n * n
    return [(r, c) for r in range(m) for c in range(m)]


def solve(n: int, clues: Dict[Cell, int]) -> Optional[Dict[Cell, int]]:
    m = n * n
    g: Dict[Cell, int] = dict(clues)
    cs = cells(n)
    for p, q in combinations(list(g), 2):
        if adjacent(n, p, q) and g[p] == g[q]:
            return None

    def cand(cell: Cell) -> List[int]:
        used = {g[o] for o in cs if o in g and adjacent(n, cell, o)}
        return [v for v in range(m) if v not in used]

    def bt() -> bool:
        empty = [c for c in cs if c not in g]
        if not empty:
            return True
        cell = min(empty, key=lambda c: len(cand(c)))
        opts = cand(cell)
        if not opts:
            return False
        for v in opts:
            g[cell] = v
            if bt():
                return True
            del g[cell]
        return False

    return dict(g) if bt() else None


def critical_density(n: int) -> float:
    return (n * n - 1) / (n * n)


if __name__ == "__main__":
    rng = random.Random(7)
    n = 2
    m = n * n
    print(f"critical density d_c({n}) = {critical_density(n):.3f}")
    for pct in range(0, 101, 20):
        d = pct / 100.0
        k = round(d * m * m)
        solved = 0
        trials = 80
        for _ in range(trials):
            chosen = rng.sample(cells(n), k)
            clues = {c: rng.randrange(m) for c in chosen}
            if solve(n, clues) is not None:
                solved += 1
        print(f"density {d:.2f}: P(solvable) ~ {solved / trials:.3f}")

