function ShiftGrid(n):
    m <- n * n
    grid <- m x m array
    for r in 0 .. m-1:
        for c in 0 .. m-1:
            grid[r][c] <- (n * (r mod n) + (r div n) + c) mod m
    return grid

function Solve(n, clues):
    g <- copy(clues)
    if g has a conflicting adjacent pair: return FAIL
    function Backtrack():
        empty <- cells not in g
        if empty is empty: return SUCCESS
        cell <- argmin over empty of |Candidates(cell)|
        for v in Candidates(cell):
            g[cell] <- v
            if Backtrack() == SUCCESS: return SUCCESS
            remove g[cell]
        return FAIL
    return g if Backtrack() == SUCCESS else FAIL

function Candidates(cell):
    used <- { g[o] : o adjacent to cell and o in g }
    return { v in 0..n^2-1 : v not in used }

